async function vault158(path,method='GET',body=null){if(!window.BDVault)throw new Error('Local Vault nicht verfügbar.');await window.BDVault.checkHealth();if(!window.BDVault.status().unlocked)await window.BDVault.ensureUnlocked();return method==='POST'?window.BDVault.post(path,body||{}):window.BDVault.request(path)}
