  host.innerHTML=filtered.length?filtered.map(r=>{const a=r.asset||{},draft=r.latestDraftVersion?`Draft V${r.latestDraftVersion}`:'noch kein Draft';return `<article class="creator-card158" data-creator-id="${esc(a.id)}"><div class="creator-icon158">${icon158(a)}</div><div class="creator-main158"><div class="creator-meta158"><span>${esc(labelType158(a))}</span><em>${esc(status158(a))}</em></div><h3>${esc(a.title||labelType158(a))}</h3><p>Aus: <strong>${esc(r.sourceTitle||'Leitartikel')}</strong></p><small>${esc(draft)} · aktualisiert ${esc(fmt(a.updatedAt))}</small></div><div class="creator-actions158"><button class="kh-primary" type="button" data-creator-open158>${a.contentType==='carousel'?'Carousel Studio':a.contentType==='video_script'?'Short Studio':'Weiterarbeiten'}</button><button class="kh-soft" type="button" data-creator-source158>Leitartikel</button></div></article>`}).join(''):'<div class="kh-empty">Noch keine Produktionsartefakte in dieser Ansicht.</div>';
