function openCreatorItem158(id){const r=creatorItems158.find(x=>x.asset?.id===id);if(!r)return;const a=r.asset||{};if(a.contentType==='carousel')return window.BDHub148?.carouselFromArtifact?.(r.sourceAssetId,a.id,r.projectId);if(a.contentType==='video_script')return openShortFromArtifact158(r.sourceAssetId,a.id,r.projectId);window.BDHub148?.openAsset?.(r.projectId,a.id)}

function installShortDirect158(){const d=$('#repurposeDialog148 .repurpose-dialog148');if(!d||d.querySelector('.youtube-direct158'))return;const existing=d.querySelector('.repurpose-direct156');if(!existing)return;const s=document.createElement('section');s.className='repurpose-direct156 youtube-direct158';s.innerHTML=`<div><span class="type">DIREKT STARTEN</span><strong>YouTube Short</strong><p>Artikel → vorbereiteter GPT-Prompt → gesprochenes Skript + On-Screen-Text → zurück ins Creator Studio.</p></div><button id="repurposeShort158" class="kh-primary" type="button">Short erstellen</button>`;existing.insertAdjacentElement('afterend',s);$('#repurposeShort158').onclick=()=>{const src=window.BDHub148?.currentSource?.();if(src?.id)openShortStudio158(src.id,'',window.BDHub148?.currentProject?.()||'');else notice158('Bitte zuerst einen Leitartikel öffnen.','warn')}}

